css:
.daloy-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d6e2ef;
    background: radial-gradient(circle at 20% -10%, #16243a 0%, #0c1626 45%, #070d18 100%);
    border-radius: 18px;
}

.daloy-container * {
    box-sizing: border-box;
}

.daloy-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0a1830 0%, #103a52 55%, #0c5b66 100%);
    color: #eafcff;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(54, 226, 213, 0.22);
    box-shadow: 0 14px 38px rgba(2, 10, 22, 0.6);
}

.daloy-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.daloy-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #36e2d5;
    background: rgba(54, 226, 213, 0.10);
    border: 1px solid rgba(54, 226, 213, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
}

.daloy-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b7d2e0;
}

.daloy-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.daloy-firm {
    flex: 1;
    background: #101e33;
    border-radius: 14px;
    padding: 14px 18px;
    border: 1px solid rgba(120, 160, 200, 0.16);
    box-shadow: 0 4px 14px rgba(2, 10, 22, 0.4);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.daloy-firm-data { border-left: 5px solid #36e2d5; }
.daloy-firm-crisis { border-left: 5px solid #ff6b6b; }

.daloy-firm-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #eafcff;
}

.daloy-firm-data .daloy-firm-name { color: #36e2d5; }
.daloy-firm-crisis .daloy-firm-name { color: #ff8a8a; }

.daloy-firm-meta {
    font-size: 0.82rem;
    color: #8ba3bb;
    line-height: 1.4;
}

.daloy-firm-plus {
    align-self: center;
    font-size: 1.8rem;
    font-weight: 800;
    color: #5fb8d6;
}

.daloy-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6cc;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.daloy-period-counter #currentDay,
.daloy-period-counter #maxPeriods {
    font-weight: 800;
    color: #36e2d5;
}

.daloy-round-name {
    background: rgba(54, 226, 213, 0.12);
    color: #36e2d5;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.daloy-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #ffc24b;
    background: rgba(255, 194, 75, 0.12);
    border: 1px solid rgba(255, 194, 75, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
}

.daloy-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.daloy-status-card {
    background: linear-gradient(160deg, #112139 0%, #0d1a2c 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(120, 160, 200, 0.14);
    box-shadow: 0 6px 16px rgba(2, 10, 22, 0.4);
    border-top: 4px solid #5fb8d6;
}

.daloy-card-lift { border-top-color: #36e2d5; }
.daloy-card-value { border-top-color: #4ade80; }
.daloy-card-accuracy { border-top-color: #5fb8d6; }
.daloy-card-deploy { border-top-color: #ffc24b; }

.daloy-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7e96ae;
}

.daloy-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eafcff;
    font-variant-numeric: tabular-nums;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
}

.daloy-card-lift .daloy-value { color: #36e2d5; }
.daloy-card-value .daloy-value { color: #4ade80; }
.daloy-card-accuracy .daloy-value { color: #5fb8d6; }
.daloy-card-deploy .daloy-value { color: #ffc24b; font-size: 1.5rem; }

.daloy-sublabel {
    font-size: 0.74rem;
    color: #6f879f;
    line-height: 1.35;
}

.daloy-card-value.daloy-value-loss .daloy-value { color: #ff6b6b; }
.daloy-card-value.daloy-value-loss { border-top-color: #ff6b6b; }
.daloy-card-lift.daloy-lift-good .daloy-value { color: #4ade80; }

.daloy-card-deploy.daloy-deploy-live { border-top-color: #4ade80; }
.daloy-card-deploy.daloy-deploy-live .daloy-value { color: #4ade80; }
.daloy-card-deploy.daloy-deploy-missed { border-top-color: #ff6b6b; }
.daloy-card-deploy.daloy-deploy-missed .daloy-value { color: #ff6b6b; }

.daloy-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #101e33;
    border: 1px solid rgba(120, 160, 200, 0.18);
    color: #9fb6cc;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.daloy-budget-bar #budgetDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #ffc24b;
    font-weight: 800;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
}

.daloy-budget-bar.daloy-budget-over #budgetDisplay { color: #ff6b6b; }

.daloy-briefing {
    display: flex;
    gap: 14px;
    background: #101e33;
    border-left: 5px solid #36e2d5;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 200, 0.12);
    border-left: 5px solid #36e2d5;
    box-shadow: 0 6px 16px rgba(2, 10, 22, 0.35);
}

.daloy-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.daloy-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eafcff;
    margin-bottom: 6px;
}

.daloy-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #b7d2e0;
}

.daloy-briefing-text strong { color: #36e2d5; }
.daloy-briefing-text em { color: #ffc24b; font-style: italic; }

.daloy-controls {
    background: #0e1c30;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 200, 0.14);
    box-shadow: 0 6px 16px rgba(2, 10, 22, 0.35);
}

.daloy-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eafcff;
    border-bottom: 2px solid rgba(120, 160, 200, 0.18);
    padding-bottom: 8px;
}

.daloy-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cbdcec;
    margin: 14px 0 6px;
}

.daloy-container select,
.daloy-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(120, 160, 200, 0.30);
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1526;
    color: #eafcff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.daloy-container select:focus,
.daloy-container input[type="number"]:focus {
    outline: none;
    border-color: #36e2d5;
    box-shadow: 0 0 0 3px rgba(54, 226, 213, 0.20);
}

.daloy-container select option {
    background-color: #0a1526;
    color: #eafcff;
}

.daloy-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #36e2d5;
}

.daloy-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6cc;
    margin-top: 4px;
}

.daloy-range-readout span:nth-child(2) {
    color: #36e2d5;
    font-weight: 800;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
}

.daloy-hint {
    font-size: 0.8rem;
    color: #7e96ae;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.daloy-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.daloy-container .btn-primary {
    background: linear-gradient(135deg, #0c8a8f 0%, #36e2d5 100%);
    border: none;
    color: #051018;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(54, 226, 213, 0.30);
}

.daloy-container .btn-primary:hover {
    filter: brightness(1.08);
}

.daloy-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid rgba(120, 160, 200, 0.34);
    color: #9fb6cc;
    background: transparent;
}

.daloy-coach {
    background: linear-gradient(160deg, #0a1830 0%, #0c2a3a 100%);
    color: #cfe6ec;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(54, 226, 213, 0.20);
    box-shadow: 0 8px 20px rgba(2, 10, 22, 0.45);
}

.daloy-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffc24b;
    margin-bottom: 8px;
}

.daloy-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.daloy-coach-body strong { color: #36e2d5; }
.daloy-coach-body em { color: #ffc24b; font-style: italic; }

.daloy-history,
.daloy-chart {
    background: #0e1c30;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 200, 0.14);
    box-shadow: 0 6px 16px rgba(2, 10, 22, 0.35);
}

.daloy-history h3,
.daloy-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eafcff;
}

.daloy-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #b7d2e0;
}

.daloy-container table#usfHistoryTable th {
    background: rgba(54, 226, 213, 0.08);
    color: #36e2d5;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(54, 226, 213, 0.24);
}

.daloy-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 160, 200, 0.12);
    color: #b7d2e0;
}

.daloy-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(120, 160, 200, 0.05);
}

.daloy-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .daloy-container {
        padding: 14px;
    }
    .daloy-header h1 {
        font-size: 1.7rem;
    }
    .daloy-firms {
        flex-direction: column;
    }
    .daloy-firm-plus {
        transform: rotate(90deg);
    }
    .daloy-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .daloy-value {
        font-size: 2rem;
    }
    .daloy-card-deploy .daloy-value {
        font-size: 1.2rem;
    }
    .daloy-clock {
        margin-left: 0;
    }
    .daloy-period-counter {
        font-size: 0.88rem;
    }
    .daloy-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .daloy-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0 completion debrief (append-only, namespaced .dwd-cm-*) ───────────── */
.dwd-cm { color: #e6f0f7; font-family: inherit; padding: 4px 2px 2px; }
.dwd-cm-head { display: flex; align-items: center; gap: 18px; margin-bottom: 16px;
    border-bottom: 1px solid rgba(120,160,200,0.18); padding-bottom: 14px; }
.dwd-cm-score { display: flex; align-items: baseline; line-height: 1;
    padding: 10px 16px; border-radius: 14px; background: rgba(54,226,213,0.10);
    border: 1px solid rgba(54,226,213,0.35); }
.dwd-cm-score-num { font-size: 2.6rem; font-weight: 800; color: #36e2d5; }
.dwd-cm-score-den { font-size: 1rem; color: #9fb6cc; margin-left: 2px; }
.dwd-cm-title { font-size: 0.82rem; letter-spacing: .5px; text-transform: uppercase;
    color: #9fb6cc; margin-bottom: 4px; }
.dwd-cm-verdict { font-size: 1.35rem; font-weight: 700; color: #e6f0f7; }
.dwd-cm-grade { display: inline-block; margin-left: 8px; padding: 1px 10px; border-radius: 999px;
    font-size: 0.9rem; font-weight: 700; background: rgba(255,255,255,0.10); color: #cfe0ee;
    vertical-align: middle; }
.dwd-cm-tier-top .dwd-cm-score { background: rgba(74,222,128,0.12); border-color: rgba(74,222,128,0.45); }
.dwd-cm-tier-top .dwd-cm-score-num { color: #4ade80; }
.dwd-cm-tier-low .dwd-cm-score { background: rgba(248,113,113,0.10); border-color: rgba(248,113,113,0.40); }
.dwd-cm-tier-low .dwd-cm-score-num { color: #f87171; }
.dwd-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 14px; }
.dwd-cm-kpi { flex: 1 1 120px; min-width: 110px; padding: 10px 12px; border-radius: 10px;
    background: rgba(120,160,200,0.08); border: 1px solid rgba(120,160,200,0.14); }
.dwd-cm-kpi-val { font-size: 1.15rem; font-weight: 700; color: #e6f0f7; }
.dwd-cm-kpi-lbl { font-size: 0.72rem; letter-spacing: .3px; text-transform: uppercase; color: #8ea6bd; margin-top: 3px; }
.dwd-cm-targets { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin-bottom: 14px;
    font-size: 0.92rem; color: #cfe0ee; }
.dwd-cm-tgt-label { font-weight: 700; color: #9fb6cc; }
.dwd-cm-chip { display: inline-block; margin-left: 6px; padding: 1px 8px; border-radius: 999px;
    font-size: 0.8rem; font-weight: 700; }
.dwd-cm-chip-ok { background: rgba(74,222,128,0.16); color: #4ade80; }
.dwd-cm-chip-no { background: rgba(248,113,113,0.16); color: #f87171; }
.dwd-cm-insights-label { font-size: 0.82rem; letter-spacing: .4px; text-transform: uppercase;
    color: #9fb6cc; margin-bottom: 6px; }
.dwd-cm-insights { margin: 0; padding-left: 20px; }
.dwd-cm-insights li { margin-bottom: 6px; line-height: 1.45; color: #d4e2ee; }

