(function() {
    'use strict';

    class DecideWithDataAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Decide with Data`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Daloy Mobility, PHP millions / points).
            this.BUDGET = 90;            // ₱90M analytics budget
            this.WINDOW_WEEKS = 13;      // 90-day proof window (~13 weeks)
            this.LIFT_BAR = 2.0;         // -2 pts cancellation ≈ board's value bar
            this.VALUE_BAR = 70;         // ₱70M/yr the lift bar is worth
            this.FN_COST = 180;          // ₱ per missed cancellation (false negative)
            this.FP_COST = 40;           // ₱ per needless intervention (false positive)

            // Model option economics (accuracy %, cost ₱M, build weeks).
            this.MODELS = {
                simple:  { acc: 82, cost: 15, weeks: 6 },
                buy:     { acc: 85, cost: 40, weeks: 8 },
                complex: { acc: 89, cost: 65, weeks: 14 }   // 14 > 13 → misses the window
            };

            // Modelled "best" choices the concept rewards.
            this.BEST_PROBLEM = `cancellation`;
            this.VALUE_THRESHOLD = 30;   // value-maximizing intervention threshold (well below 50%)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    lift: 0,                 // decision lift in pts on the target operating metric
                    value: 0,                // net annual value, ₱M/yr (can go negative)
                    accuracy: 0,             // model accuracy %, 0 until a model is chosen
                    deployStatus: `pending`, // pending | ontrack | live | missed | undecided
                    budgetSpent: 0,          // ₱M committed of the 90M budget

                    // Sticky, run-defining penalty flags. Once set true they persist
                    // and gate the top verdict / cap KPIs — a later good round cannot wash them out.
                    flagWrongProblem: false,   // chose the convenient/least-valuable problem
                    flagNotDeployed: false,    // chose a model that cannot ship in 90 days (HEADLINE error)
                    flagNoThreshold: false,    // never set a decision threshold → model changes no decision
                    flagAccuracyThreshold: false, // tuned threshold for accuracy, not value
                    flagNoMonitoring: false,   // no drift monitoring / rollback
                    flagReportedAccuracy: false,  // pitched AUC/tech to the board instead of lift

                    problem: ``,             // chosen prediction problem
                    model: ``,               // chosen model class
                    chosenThreshold: 0,      // intervention threshold set in R3

                    liftHistory: [0],
                    valueHistory: [0],
                    accuracyHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors so a blind
                // click-through does NOT auto-win.
                state.decisions = {
                    problem: `eta`,            // the convenient-data problem, not the valuable one
                    metric: `accuracy`,        // success as a model statistic, not a decision
                    framing: `prediction`,     // start from the model, not the decision
                    valueWeight: 35,
                    model: `complex`,          // the headline accuracy-chasing error → cannot deploy
                    data: `raw`,
                    measure: `none`,
                    speed: 50,
                    objective: `accuracy`,     // accuracy-max threshold, leaves money on the table
                    threshold: 50,             // the accuracy-max point, not the value-max one
                    loop: `all`,
                    monitor: `none`,           // one-time deployment, no drift monitoring
                    pitch: `auc`,              // report AUC to the board
                    shock: `drift`,
                    response: `overclaim`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`problemInput`);
                const me = document.getElementById(`metricInput`);
                const fr = document.getElementById(`framingInput`);
                const vw = document.getElementById(`valueWeightInput`);
                if (pr) decisions.problem = pr.value;
                if (me) decisions.metric = me.value;
                if (fr) decisions.framing = fr.value;
                if (vw) decisions.valueWeight = parseInt(vw.value, 10);
                if (!Number.isFinite(decisions.valueWeight) || decisions.valueWeight < 0 || decisions.valueWeight > 100) {
                    warn(`warn_valueweight_range`); return false;
                }
            } else if (round === 2) {
                const mo = document.getElementById(`modelInput`);
                const da = document.getElementById(`dataInput`);
                const ms = document.getElementById(`measureInput`);
                const sp = document.getElementById(`speedInput`);
                if (mo) decisions.model = mo.value;
                if (da) decisions.data = da.value;
                if (ms) decisions.measure = ms.value;
                if (sp) decisions.speed = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 3) {
                const ob = document.getElementById(`objectiveInput`);
                const th = document.getElementById(`thresholdInput`);
                const lo = document.getElementById(`loopInput`);
                const mn = document.getElementById(`monitorInput`);
                if (ob) decisions.objective = ob.value;
                if (th) decisions.threshold = parseInt(th.value, 10);
                if (lo) decisions.loop = lo.value;
                if (mn) decisions.monitor = mn.value;
                if (!Number.isFinite(decisions.threshold) || decisions.threshold < 10 || decisions.threshold > 90) {
                    warn(`warn_threshold_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const sh = document.getElementById(`shockInput`);
                const re = document.getElementById(`responseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (sh) decisions.shock = sh.value;
                if (re) decisions.response = re.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Frame the prediction problem (Common Error 4: convenient vs valuable). ----
                ds.problem = d.problem;
                const valueW = d.valueWeight / 100;

                // Problem business potential: cancellation targets the bleeding 14% rate;
                // demand is mid-value; ETA fights the rival on its strongest turf.
                let problemPotential;
                switch (d.problem) {
                    case `cancellation`: problemPotential = 1.0; break;
                    case `demand`: problemPotential = 0.65; break;
                    case `eta`: default: problemPotential = 0.4; break;
                }
                ds.problemPotential = problemPotential;

                // Choosing ETA (cleanest data) is the convenient-problem trap unless you
                // explicitly weight business value high AND it's genuinely your read.
                // Picking the low-value problem while weighting data convenience sets the sticky flag.
                if (d.problem === `eta` && valueW < 0.5) {
                    ds.flagWrongProblem = true;
                    coachKey = `coach_r1_convenient`;
                } else if (d.problem === `cancellation` && valueW >= 0.5 && d.metric === `decision` && d.framing === `chain`) {
                    coachKey = `coach_r1_sharp`;
                } else if (d.problem === `demand`) {
                    coachKey = `coach_r1_demand`;
                }

                // Framing as a decision, not a model statistic (Key concept: prediction vs decision).
                if (d.metric === `accuracy`) {
                    ds.flagWrongMetric = true;
                    if (coachKey === `coach_default`) coachKey = `coach_r1_metric`;
                } else if (d.metric === `adoption`) {
                    ds.flagWrongMetric = true;
                    if (coachKey === `coach_default`) coachKey = `coach_r1_adoption`;
                } else {
                    ds.flagWrongMetric = false;
                }

                if (d.framing === `vague`) {
                    ds.flagVagueFraming = true;
                    if (coachKey === `coach_default`) coachKey = `coach_r1_vague`;
                } else if (d.framing === `prediction`) {
                    if (coachKey === `coach_default`) coachKey = `coach_r1_prediction`;
                } else {
                    ds.flagVagueFraming = false;
                }

                // No KPI movement yet — framing sets the ceiling, not the score.
                ds.deployStatus = `pending`;

                summaryKey = (d.problem === `cancellation` && d.metric === `decision` && d.framing === `chain`)
                    ? `sum_r1_good`
                    : (ds.flagWrongProblem ? `sum_r1_convenient` : `sum_r1_weak`);
            } else if (round === 2) {
                // ---- Model-and-data strategy: the accuracy-vs-cost trade-off (Common Error 1). ----
                ds.model = d.model;
                const m = this.MODELS[d.model] || this.MODELS.simple;
                ds.accuracy = m.acc;
                ds.budgetSpent = Math.min(this.BUDGET + 30, ds.budgetSpent + m.cost);

                // Effective build time. Raw-GPS engineering adds weeks; existing features save a little.
                // A deep spatio-temporal net is intrinsically a 14-week build — its raw-GPS pipeline
                // is inseparable from the model, so feature shortcuts and throttle cannot rescue it.
                let weeks = m.weeks;
                if (d.model === `complex`) {
                    // The complex model is locked to its over-window build; throttle shaves at most 1 week.
                    weeks -= Math.round((d.speed / 100) * 1);   // 14 → min 13, but the trip-cost gate uses >13
                } else {
                    if (d.data === `raw`) weeks += 3; else weeks -= 1;
                    weeks -= Math.round((d.speed / 100) * 1);
                }

                // HEADLINE anti-pattern: a model that cannot deploy inside the 90-day window.
                // The complex deep-net is a 14-week build — it ALWAYS misses the 90-day window, and no
                // throttle or feature shortcut changes that (this is the run-defining accuracy-chasing trap).
                // The other models miss only if a from-scratch raw-GPS pipeline pushes them over 13 weeks.
                const missesWindow = (d.model === `complex`) || (weeks > this.WINDOW_WEEKS);
                if (missesWindow) {
                    ds.flagNotDeployed = true;
                    ds.deployStatus = `missed`;
                    coachKey = (d.model === `complex`) ? `coach_r2_complex` : `coach_r2_missed`;
                } else {
                    ds.flagNotDeployed = false;
                    ds.deployStatus = `ontrack`;
                    if (d.model === `simple`) coachKey = `coach_r2_simple`;
                    else if (d.model === `buy`) coachKey = `coach_r2_buy`;
                }
                ds.buildWeeks = weeks;

                // Buying a black box forfeits threshold control downstream.
                ds.flagBlackBox = (d.model === `buy`);

                // Measurement design: only a live A/B test proves production lift (Decision lift concept).
                if (d.measure === `abtest`) {
                    ds.flagNoBaseline = false;
                } else {
                    ds.flagNoBaseline = true;
                    if (coachKey === `coach_default` || coachKey === `coach_r2_simple`) coachKey = `coach_r2_nobaseline`;
                }

                // Over-budget warning flag.
                ds.flagOverBudget = ds.budgetSpent > this.BUDGET;

                summaryKey = ds.flagNotDeployed
                    ? `sum_r2_notdeployed`
                    : (d.model === `simple` && d.data === `existing` && d.measure === `abtest`
                        ? `sum_r2_good`
                        : (d.model === `buy` ? `sum_r2_buy` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Deployment threshold: the threshold, not the model, makes the outcome. ----
                ds.chosenThreshold = d.threshold;

                // Forgetting the threshold (Common Error 2): the model changes no decision.
                if (d.objective === `none`) {
                    ds.flagNoThreshold = true;
                    ds.deployStatus = (ds.deployStatus === `missed`) ? `missed` : `undecided`;
                    coachKey = `coach_r3_nothreshold`;
                } else if (d.objective === `accuracy`) {
                    // Accuracy-max threshold with asymmetric costs leaves money on the table (Common Error 5).
                    ds.flagAccuracyThreshold = true;
                    coachKey = `coach_r3_accuracy`;
                } else {
                    ds.flagAccuracyThreshold = false;
                    coachKey = `coach_r3_value`;
                }

                // How close the chosen threshold sits to the value-maximizing point (~30%).
                // Distance from 30 scales the share of the cost-weighted value captured.
                const dist = Math.abs(d.threshold - this.VALUE_THRESHOLD);
                ds.thresholdQuality = Math.max(0, 1 - dist / 45);   // 1.0 at 30%, decays toward the extremes
                if (d.objective === `value` && d.threshold <= 35 && d.threshold >= 20) coachKey = `coach_r3_valuetuned`;
                if (d.objective === `value` && d.threshold >= 55) coachKey = `coach_r3_tooconservative`;

                // Human-in-the-loop boundary: tiered scales safely; all-auto risks costly errors; all-manual never scales.
                switch (d.loop) {
                    case `tiered`: ds.loopFactor = 1.0; break;
                    case `all`: ds.loopFactor = 0.8; if (coachKey === `coach_r3_value` || coachKey === `coach_r3_valuetuned`) coachKey = `coach_r3_autoall`; break;
                    case `manual`: ds.loopFactor = 0.55; if (coachKey === `coach_default`) coachKey = `coach_r3_manual`; break;
                    default: ds.loopFactor = 0.8;
                }

                // Monitoring / rollback (Common Error 5 & concept drift).
                if (d.monitor === `drift`) {
                    ds.flagNoMonitoring = false;
                } else {
                    ds.flagNoMonitoring = true;
                    if (coachKey === `coach_r3_value` || coachKey === `coach_r3_valuetuned`) coachKey = `coach_r3_nomonitor`;
                }

                summaryKey = ds.flagNoThreshold
                    ? `sum_r3_nothreshold`
                    : (ds.flagAccuracyThreshold
                        ? `sum_r3_accuracy`
                        : (d.loop === `tiered` && d.monitor === `drift` && ds.thresholdQuality >= 0.85
                            ? `sum_r3_good`
                            : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Defend the initiative and absorb the shock. ----
                // Reporting accuracy/tech instead of lift loses the board (Common Error 3).
                switch (d.pitch) {
                    case `lift`: ds.flagReportedAccuracy = false; coachKey = `coach_r4_lift`; break;
                    case `auc`: ds.flagReportedAccuracy = true; coachKey = `coach_r4_auc`; break;
                    case `tech`: ds.flagReportedAccuracy = true; coachKey = `coach_r4_tech`; break;
                }

                // Shock response: adapt (keep discipline) vs over-claim / abandon.
                switch (d.response) {
                    case `adapt`: ds.shockHandled = true; if (coachKey === `coach_r4_lift`) coachKey = `coach_r4_adapt`; break;
                    case `overclaim`: ds.shockHandled = false; coachKey = `coach_r4_overclaim`; break;
                    case `abandon`: ds.shockHandled = false; coachKey = `coach_r4_abandon`; break;
                }
                ds.shockChoice = d.shock;

                // A privacy shock with granular GPS is sharper if you built the raw-GPS model.
                if (d.shock === `privacy` && ds.model === `complex` && d.response !== `adapt`) {
                    coachKey = `coach_r4_privacy`;
                }

                // Conviction reinforces the deployed-82-beats-undeployed-89 lesson.
                ds.convictionHeld = d.conviction >= 55;

                summaryKey = (d.pitch === `lift` && d.response === `adapt`)
                    ? `sum_r4_good`
                    : (ds.flagReportedAccuracy ? `sum_r4_accuracy` : `sum_r4_weak`);
            }

            // =====================================================================
            // RECOMPUTE the cost-weighted economics from sticky state every round.
            // Lift and value are DERIVED so the sticky penalty flags can hard-gate them.
            // =====================================================================
            this._recompute(ds);

            ds.liftHistory.push(ds.lift);
            ds.valueHistory.push(ds.value);
            ds.accuracyHistory.push(ds.accuracy);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // ── Persist the composite where the grading/reporting layer reads it ──
            // express_resolveDomainScore() → domainState.performance.overallScore (then top-level score);
            // express_extractHistory() reads the SAME path from each period's history snapshot;
            // express_compute_grade() (gametype 20) posts it back via AGS. Without this the
            // gradebook shows "—", the sparkline is empty and every LTI grade is 0.
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.performance.grade = this._gradeLetter(composite);
            ds.score = composite;

            return {
                period: state.currentPeriod,
                lift: ds.lift,
                value: ds.value,
                accuracy: ds.accuracy,
                deployStatus: ds.deployStatus,
                deployLabel: this._deployLabel(ds.deployStatus),
                budgetSpent: ds.budgetSpent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

        // Derive decision lift (pts) and net value (₱M/yr) from the run's sticky state.
        _recompute(ds) {
            // Before a model is chosen there is no lift.
            if (!ds.model) {
                ds.lift = 0;
                ds.value = 0;
                return;
            }

            // 1) A model that never shipped produces ZERO lift and a pure loss (sunk build cost).
            if (ds.flagNotDeployed) {
                ds.lift = 0;
                ds.value = -ds.budgetSpent;   // brilliant notebook, nothing live — money burned
                return;
            }

            // 2) A model with no decision threshold changes no decision → zero lift, sunk cost.
            if (ds.flagNoThreshold) {
                ds.lift = 0;
                ds.value = -ds.budgetSpent;
                return;
            }

            // ---- The model is live and acts. Build the lift from accuracy × the right problem ×
            //      a value-tuned threshold × the human-in-the-loop boundary. ----
            const accFactor = (ds.accuracy - 70) / 20;            // 82%→0.6, 85%→0.75, 89%→0.95
            const potential = ds.problemPotential || 0.4;          // cancellation 1.0, demand .65, eta .4
            let thrQ = (ds.thresholdQuality != null) ? ds.thresholdQuality : 0.0;
            const loopF = ds.loopFactor || 0.8;

            // Accuracy-tuned threshold captures only part of the value of a value-tuned one.
            if (ds.flagAccuracyThreshold) thrQ = Math.min(thrQ, 0.55);
            // A bought black box you can't tune caps threshold quality too.
            if (ds.flagBlackBox) thrQ = Math.min(thrQ, 0.7);

            // Decision lift, in pts on the target operating metric. Bar = 2.0 pts.
            // The disciplined simple-model path (82% deployed, cancellation, value-tuned at ~30%, tiered)
            // clears the bar at ~2.2 pts. The complex 89% model can never deploy, so it scores 0 — a
            // deployed 82% beats an undeployed 89%. Buying the black box caps thrQ at 0.7, keeping it
            // just under the bar despite higher accuracy (you cannot tune what you do not control).
            let lift = 3.7 * accFactor * potential * thrQ * loopF;

            // Wrong (convenient) problem caps the achievable lift hard — even a great model
            // on a low-value decision cannot clear the board's bar.
            if (ds.flagWrongProblem) lift = Math.min(lift, this.LIFT_BAR - 0.4);

            // No drift monitoring: silent degradation shaves the realised, durable lift.
            if (ds.flagNoMonitoring) lift *= 0.78;

            ds.lift = Math.round(lift * 10) / 10;

            // ---- Net annual value (₱M/yr): cost-weighted, net of build cost. ----
            // Each point of lift on this decision is worth ~₱35M/yr (2 pts ≈ ₱70M).
            let gross = ds.lift * (this.VALUE_BAR / this.LIFT_BAR);

            // No baseline / A-B test: you cannot prove the lift to the board, so only part counts.
            if (ds.flagNoBaseline) gross *= 0.7;

            // Net of the build cost committed.
            let net = gross - ds.budgetSpent;
            ds.value = Math.round(net);
        }

        _deployLabel(s) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            switch (s) {
                case `live`: return t(`deploy_live`);
                case `ontrack`: return t(`deploy_ontrack`);
                case `missed`: return t(`deploy_missed`);
                case `undecided`: return t(`deploy_undecided`);
                default: return t(`deploy_pending`);
            }
        }

        // ── Composite score (0-100). VERBATIM v1.0.0 formula from getPerformanceSummary,
        //    factored into a helper so calculateResults can persist it every period and
        //    getPerformanceSummary reuses it (persisted == completion by construction). ──
        _composite(ds) {
            const lift = Math.round((ds.lift || 0) * 10) / 10;
            const value = Math.round(ds.value || 0);
            const accuracy = Math.round(ds.accuracy || 0);
            const liftScore = Math.max(0, Math.min(100, (lift / 2.2) * 100));
            const valueScore = Math.max(0, Math.min(100, ((value + 65) / 130) * 100));
            const accScore = Math.max(0, Math.min(100, (accuracy / 89) * 100));
            return Math.round(liftScore * 0.5 + valueScore * 0.35 + accScore * 0.15);
        }

        // Letter band for the instructor gradebook (express_extractMetrics reads
        // domainState.performance.grade; AGS post-back carries it as grade_letter).
        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 55) return `C`;
            if (c >= 40) return `D`;
            return `F`;
        }

        // Localized label for a verdict tier. The English tier id stays the stable
        // internal key used by the scoring logic; only the DISPLAY is localized.
        _gradeLabel(perfKey) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Lift Proven': 'verdict_liftproven',
                'Shipped Lift': 'verdict_shippedlift',
                'Notebook, Not Production': 'verdict_notebook',
                'No Decision Changed': 'verdict_nodecision',
                'Partial Lift': 'verdict_partial',
                'Credibility Burned': 'verdict_credburned'
            };
            const key = map[perfKey];
            return key ? t(key) : perfKey;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`liftDisplay`, `domainState.lift`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.daloy-card-lift`);
                if (card) card.classList.toggle(`daloy-lift-good`, n >= self.LIFT_BAR);
                return `${self._fmtNum(n, 1)} ${window.mySimulation.t(`unit_pts`)}`;
            });

            uiManager.bind(`valueDisplay`, `domainState.value`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.daloy-card-value`);
                if (card) card.classList.toggle(`daloy-value-loss`, n < 0);
                return n < 0 ? `−₱${Math.abs(n)}M` : `₱${n}M`;
            });

            uiManager.bind(`accuracyDisplay`, `domainState.accuracy`, (v) => {
                const n = Math.round(Number(v));
                return n > 0 ? `${n}%` : `—`;
            });

            uiManager.bind(`deployDisplay`, `domainState.deployStatus`, (v) => {
                const s = String(v);
                const card = document.querySelector(`.daloy-card-deploy`);
                if (card) {
                    card.classList.toggle(`daloy-deploy-live`, s === `live` || s === `ontrack`);
                    card.classList.toggle(`daloy-deploy-missed`, s === `missed` || s === `undecided`);
                }
                return self._deployLabel(s);
            });

            uiManager.bind(`budgetDisplay`, `domainState.budgetSpent`, (v) => {
                const n = Math.round(Number(v));
                const bar = document.querySelector(`.daloy-budget-bar`);
                if (bar) bar.classList.toggle(`daloy-budget-over`, n > self.BUDGET);
                return `₱${n}M / ₱${self.BUDGET}M`;
            });

            // Slider readouts.
            const bindReadout = (inputId, readoutId) => {
                const inp = document.getElementById(inputId);
                const out = document.getElementById(readoutId);
                if (inp && out) {
                    out.textContent = inp.value;
                    inp.addEventListener(`input`, function() { out.textContent = inp.value; });
                }
            };
            bindReadout(`valueWeightInput`, `valueWeightReadout`);
            bindReadout(`speedInput`, `speedReadout`);
            bindReadout(`thresholdInput`, `thresholdReadout`);
        }

        _fmtNum(v, dp) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(dp);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation)
                : (k) => ({ chart_ds_lift: `Decision lift (×10 pts)`, chart_ds_value: `Net value (₱M/yr)`, chart_ds_accuracy: `Model accuracy (%)`, chart_axis_left: `accuracy % · lift ×10`, chart_axis_value: `₱M/yr`, chart_axis_round: `Round` }[k] || k);
            return {
                daloyChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_ds_lift`),
                                data: [],
                                borderColor: `#36e2d5`,
                                backgroundColor: `rgba(54,226,213,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#36e2d5`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_value`),
                                data: [],
                                borderColor: `#4ade80`,
                                backgroundColor: `rgba(74,222,128,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4ade80`,
                                yAxisID: `yValue`
                            },
                            {
                                label: t(`chart_ds_accuracy`),
                                data: [],
                                borderColor: `#5fb8d6`,
                                backgroundColor: `rgba(95,184,214,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#5fb8d6`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb6cc`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7e96ae` }, grid: { color: `rgba(120,160,200,0.10)` },
                                title: { display: true, text: t(`chart_axis_left`), color: `#7e96ae` }
                            },
                            yValue: {
                                position: `right`, suggestedMin: -90, suggestedMax: 120,
                                ticks: { color: `#4ade80` }, grid: { display: false },
                                title: { display: true, text: t(`chart_axis_value`), color: `#4ade80` }
                            },
                            x: {
                                ticks: { color: `#7e96ae` }, grid: { color: `rgba(120,160,200,0.06)` },
                                title: { display: true, text: t(`chart_axis_round`), color: `#7e96ae` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.liftHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Lift is in pts (0–~3) — scale ×10 to share the 0–100 axis with accuracy.
            const liftScaled = ds.liftHistory.map((v) => Math.round(v * 10));
            return {
                daloyChart: {
                    labels: labels,
                    datasets: [
                        { data: liftScaled },
                        { data: ds.valueHistory.map((v) => Math.round(v)) },
                        { data: ds.accuracyHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const lift = Math.round(ds.lift * 10) / 10;
            const value = Math.round(ds.value);
            const accuracy = Math.round(ds.accuracy);

            const deployed = !ds.flagNotDeployed && !ds.flagNoThreshold;
            // The board's primary bar is decision lift (≥2.0 pts). Net annual value must also be
            // solidly positive (the gross lift comfortably repays the one-time build cost in year one).
            const clearedBar = lift >= this.LIFT_BAR && value >= 40;

            // Identify the run-defining pattern.
            let pattern = `mixed`;
            if (ds.flagNotDeployed) pattern = `notdeployed`;
            else if (ds.flagNoThreshold) pattern = `nothreshold`;
            else if (ds.flagWrongProblem) pattern = `wrongproblem`;
            else if (ds.flagAccuracyThreshold) pattern = `accuracythreshold`;
            else if (clearedBar && !ds.flagReportedAccuracy && !ds.flagNoMonitoring) pattern = `lift`;

            // Composite (0–100): lift dominates, value next, accuracy a minor input.
            // liftScore is normalised so the disciplined ~2.2-pt run reads near the top.
            const composite = this._composite(ds);

            // Verdict. The HEADLINE anti-patterns hard-gate the top result.
            let performance = `Credibility Burned`;
            if (deployed && clearedBar && !ds.flagReportedAccuracy && !ds.flagNoMonitoring && !ds.flagWrongProblem && composite >= 78) {
                performance = `Lift Proven`;
            } else if (deployed && clearedBar && !ds.flagWrongProblem) {
                performance = `Shipped Lift`;          // real lift, but communication or monitoring weak
            } else if (ds.flagNotDeployed) {
                performance = `Notebook, Not Production`; // accuracy-chasing missed the window
            } else if (ds.flagNoThreshold) {
                performance = `No Decision Changed`;      // forgot the threshold
            } else if (deployed && lift > 0 && composite >= 48) {
                performance = `Partial Lift`;
            }

            const insights = [];
            if (pattern === `lift`) insights.push(window.mySimulation.t(`insight_lift`));
            else if (pattern === `notdeployed`) insights.push(window.mySimulation.t(`insight_notdeployed`));
            else if (pattern === `nothreshold`) insights.push(window.mySimulation.t(`insight_nothreshold`));
            else if (pattern === `wrongproblem`) insights.push(window.mySimulation.t(`insight_wrongproblem`));
            else if (pattern === `accuracythreshold`) insights.push(window.mySimulation.t(`insight_accuracythreshold`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.flagReportedAccuracy && deployed && clearedBar) insights.push(window.mySimulation.t(`insight_reportedaccuracy`));
            if (ds.flagNoMonitoring && deployed) insights.push(window.mySimulation.t(`insight_nomonitoring`));
            if (ds.flagNoBaseline && deployed) insights.push(window.mySimulation.t(`insight_nobaseline`));
            if (ds.flagOverBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (deployed && clearedBar && !ds.flagWrongProblem) insights.push(window.mySimulation.t(`insight_deployedwins`));

            return {
                lift: lift,
                value: value,
                accuracy: accuracy,
                deployed: deployed,
                clearedBar: clearedBar,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── Localized completion debrief. The base class discards the composite,
        //    verdict, target status and insights the sim already computes and prints a
        //    generic "You completed N periods." This override surfaces them. ──
        formatCompletionMessage(summary) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = (summary && typeof summary === `object`) ? summary : {};
            const ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState)
                ? window.mySimulation.state.domainState : {};
            const composite = (s.composite != null) ? s.composite : this._composite(ds);
            const verdict = this._gradeLabel(s.performance || `Credibility Burned`);
            const grade = this._gradeLetter(composite);
            const lift = (s.lift != null) ? s.lift : Math.round((ds.lift || 0) * 10) / 10;
            const value = (s.value != null) ? s.value : Math.round(ds.value || 0);
            const accuracy = (s.accuracy != null) ? s.accuracy : Math.round(ds.accuracy || 0);
            const deployed = (s.deployed != null) ? s.deployed : (!ds.flagNotDeployed && !ds.flagNoThreshold);
            const cleared = (s.clearedBar != null) ? s.clearedBar : (lift >= this.LIFT_BAR && value >= 40);
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const valStr = value < 0 ? `−₱${Math.abs(value)}M` : `₱${value}M`;
            const accStr = accuracy > 0 ? `${accuracy}%` : `—`;
            const met = (ok) => ok
                ? `<span class="dwd-cm-chip dwd-cm-chip-ok">✓ ${t(`cm_met`)}</span>`
                : `<span class="dwd-cm-chip dwd-cm-chip-no">✗ ${t(`cm_missed`)}</span>`;

            const kpis = [
                { label: t(`cm_kpi_lift`), val: `${this._fmtNum(lift, 1)} ${t(`unit_pts`)}` },
                { label: t(`cm_kpi_value`), val: valStr },
                { label: t(`cm_kpi_accuracy`), val: accStr },
                { label: t(`cm_kpi_deploy`), val: this._deployLabel(ds.deployStatus || `pending`) }
            ].map((k) => `<div class="dwd-cm-kpi"><div class="dwd-cm-kpi-val">${k.val}</div><div class="dwd-cm-kpi-lbl">${k.label}</div></div>`).join(``);

            const insightsHtml = insights.length
                ? `<div class="dwd-cm-insights-wrap"><div class="dwd-cm-insights-label">${t(`cm_insights_label`)}</div><ul class="dwd-cm-insights">${insights.map((i) => `<li>${i}</li>`).join(``)}</ul></div>`
                : ``;

            const tierClass = `dwd-cm-tier-` + (composite >= 78 ? `top` : (composite >= 48 ? `mid` : `low`));

            return `
                <div class="dwd-cm ${tierClass}">
                    <div class="dwd-cm-head">
                        <div class="dwd-cm-score"><span class="dwd-cm-score-num">${composite}</span><span class="dwd-cm-score-den">/100</span></div>
                        <div class="dwd-cm-headmeta">
                            <div class="dwd-cm-title">${t(`cm_title`)}</div>
                            <div class="dwd-cm-verdict">${verdict} <span class="dwd-cm-grade">${grade}</span></div>
                        </div>
                    </div>
                    <div class="dwd-cm-kpis">${kpis}</div>
                    <div class="dwd-cm-targets">
                        <span class="dwd-cm-tgt-label">${t(`cm_targets_label`)}</span>
                        <span class="dwd-cm-tgt">${t(`cm_target_bar`)} ${met(cleared)}</span>
                        <span class="dwd-cm-tgt">${t(`cm_target_deploy`)} ${met(deployed)}</span>
                    </div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.flagNotDeployed) return window.mySimulation.t(`hint_notdeployed`);
            if (ds.flagNoThreshold) return window.mySimulation.t(`hint_nothreshold`);
            if (ds.flagWrongProblem) return window.mySimulation.t(`hint_wrongproblem`);
            if (ds.flagAccuracyThreshold) return window.mySimulation.t(`hint_accuracythreshold`);
            if (ds.flagNoMonitoring && state.currentPeriod >= 3) return window.mySimulation.t(`hint_nomonitoring`);
            if (ds.flagReportedAccuracy) return window.mySimulation.t(`hint_reportedaccuracy`);
            if (ds.lift >= this.LIFT_BAR && ds.value >= 40) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.lift`, label: `Lift`, i18nKey: `col_lift`, formatter: (v) => `${self._fmtNum(Number(v), 1)}` },
                { key: `results.value`, label: `Value`, i18nKey: `col_value`, formatter: (v) => { const n = Math.round(Number(v)); return n < 0 ? `−₱${Math.abs(n)}M` : `₱${n}M`; } },
                { key: `results.accuracy`, label: `Accuracy`, i18nKey: `col_accuracy`, formatter: (v) => { const n = Math.round(Number(v)); return n > 0 ? `${n}%` : `—`; } },
                { key: `results.deployLabel`, label: `Deploy`, i18nKey: `col_deploy` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

